<?php require 'config/database.php'; $pageTitle='Students'; if(isset($_GET['delete'])){$q=$pdo->prepare('DELETE FROM students WHERE id=?');$q->execute([(int)$_GET['delete']]);header('Location: students.php');exit;} $q=trim($_GET['q']??''); if($q){$s=$pdo->prepare('SELECT * FROM students WHERE roll_no LIKE ? OR name LIKE ? OR department LIKE ? ORDER BY id DESC');$like="%$q%";$s->execute([$like,$like,$like]);$rows=$s->fetchAll();}else{$rows=$pdo->query('SELECT * FROM students ORDER BY id DESC')->fetchAll();} require 'includes/header.php'; ?>
<div class="d-flex justify-content-between mb-3"><h2>Students</h2><a class="btn btn-primary" href="student_form.php">+ Add Student</a></div><form class="row g-2 mb-3"><div class="col-10"><input class="form-control" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search students"></div><div class="col-2"><button class="btn btn-dark w-100">Search</button></div></form><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Roll No</th><th>Name</th><th>Email</th><th>Department</th><th>Semester</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=htmlspecialchars($r['roll_no'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=htmlspecialchars($r['department'])?></td><td><?=$r['semester']?></td><td><a class="btn btn-sm btn-outline-primary" href="student_form.php?id=<?=$r['id']?>">Edit</a> <a data-confirm-delete class="btn btn-sm btn-outline-danger" href="students.php?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
